# Surgical: Institutional ranking
# Generated from JuliaBUGS.BUGSExamples.VOLUME_1.surgical_simple
using JuliaBUGS

model_def = JuliaBUGS.@bugs("""
model {
    for( i in 1 : N ) {
        p[i] ~ dbeta(1.0, 1.0)
        r[i] ~ dbin(p[i], n[i])
    }
}
""", false)

build_model(data) = JuliaBUGS.compile(model_def, data)
